WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY shipped_date DESC NULLS LAST, id) AS row_num FROM shipments QUALIFY row_num = 1) SELECT CASE WHEN cost >= 99 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, DATE_TRUNC('QUARTER', delivered_date) AS quarter_start, SIZE(COLLECT_SET(carrier)) AS num_carriers, ROUND(AVG(cost), 2) AS avg_cost, APPROX_PERCENTILE(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, RANK() OVER (PARTITION BY CASE WHEN cost >= 99 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(cost), 2) DESC) AS avg_cost_rank FROM ranked GROUP BY CASE WHEN cost >= 99 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', delivered_date)
